<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { Boxes, Cable, Check, CheckCircle2, CircleAlert, Clock3, Cpu, EyeOff, GripVertical, MemoryStick, MonitorOff, MoveDown, MoveUp, Network, RadioTower, RefreshCw, RotateCcw, RotateCw, Server, Settings2, Timer, TriangleAlert, Users, X } from 'lucide-vue-next'
import MetricCard from '../components/MetricCard.vue'
import { api } from '../api'; import { auth } from '../auth'; import { t, tr } from '../preferences'
import type { ClusterState, DashboardLayout, Diagnostics, Infrastructure, LiveConnectionSnapshot, PresenceSnapshot, ServiceCommand } from '../types'
type WidgetID='online-devices'|'offline-devices'|'users'|'users-online'|'active-connections'|'cluster'|'rendezvous-peers'|'relay-load'|'diagnostics'|'hbbs-sync'|'status-strip'
const defaults:WidgetID[]=['online-devices','offline-devices','users','users-online','active-connections','cluster','rendezvous-peers','relay-load','diagnostics','hbbs-sync','status-strip']
const labels:Record<WidgetID,[string,string]>={'online-devices':['Устройства в сети','Online devices'],'offline-devices':['Устройства офлайн','Offline devices'],users:['Пользователи','Users'],'users-online':['Пользователи онлайн','Users online'],'active-connections':['Активные подключения','Active connections'],cluster:['Узлы кластера','Cluster nodes'],'rendezvous-peers':['Rendezvous peers','Rendezvous peers'],'relay-load':['Relay-нагрузка','Relay load'],diagnostics:['Самодиагностика сервера','Server self-diagnostics'],'hbbs-sync':['Синхронизация HBBS','HBBS synchronization'],'status-strip':['Состояние контейнера','Container status']}
const infrastructure=ref<Infrastructure|null>(null),diagnostics=ref<Diagnostics|null>(null),presence=ref<PresenceSnapshot|null>(null),connections=ref<LiveConnectionSnapshot|null>(null),cluster=ref<ClusterState|null>(null),commands=ref<ServiceCommand[]>([])
const loading=ref(true),error=ref(''),operationsError=ref(''),commandBusy=ref(false),now=ref(new Date())
const presenceDialog=ref<HTMLDialogElement|null>(null),presenceLoading=ref(false),presenceError=ref(''),presenceSearch=ref('')
const onlineUsers=computed(()=>presence.value?.users.filter(user=>user.state==='online')??[])
const filteredOnlineUsers=computed(()=>{const query=presenceSearch.value.trim().toLocaleLowerCase();return onlineUsers.value.filter(user=>`${user.display_name} ${user.username} ${user.client_device_id??''}`.toLocaleLowerCase().includes(query))})
function openOnlineUsers(){if(!auth.can('users.read'))return;presenceSearch.value='';presenceDialog.value?.showModal();void loadPresence()}
function seenAt(value?:string){if(!value||value.startsWith('0001-'))return '—';const date=new Date(value);return Number.isNaN(date.getTime())?'—':date.toLocaleString()}
const layout=ref<DashboardLayout>({version:1,order:[...defaults],hidden:[]}),savedLayout=ref<DashboardLayout>({version:1,order:[...defaults],hidden:[]})
const customizing=ref(false),layoutBusy=ref(false),layoutError=ref(''),dragging=ref<WidgetID|null>(null)
const displayName=computed(()=>auth.state.user?.display_name||auth.state.user?.username||'Administrator')
const operational=computed(()=>infrastructure.value?.api==='online'&&infrastructure.value?.hbbs==='online'&&infrastructure.value?.hbbr==='online')
const ordered=computed(()=>layout.value.order.filter((id):id is WidgetID=>defaults.includes(id as WidgetID)))
function canShow(id:WidgetID){if(id==='users-online')return auth.can('users.read');if(id==='active-connections')return auth.can('audit.read');return true}
const visible=computed(()=>ordered.value.filter(id=>!layout.value.hidden.includes(id)&&canShow(id))),hidden=computed(()=>ordered.value.filter(id=>layout.value.hidden.includes(id)&&canShow(id)))
function clone(v:DashboardLayout):DashboardLayout{const order=[...v.order];for(const id of defaults)if(!order.includes(id))order.push(id);return{version:1,order,hidden:[...v.hidden]}}
function widgetClass(id:WidgetID){return ['diagnostics','status-strip'].includes(id)?'full':id==='hbbs-sync'?'wide':'metric'}
function formatRate(v:number|undefined){const n=v||0;return n<1024?`${n} B/s`:n<1024**2?`${(n/1024).toFixed(1)} KiB/s`:`${(n/1024**2).toFixed(1)} MiB/s`}
function formatMemory(v:number|undefined){return`${((v||0)/1024/1024).toFixed(1)} MiB`}
function formatUptime(v:number|undefined){const n=Math.max(0,Math.floor(v||0)),d=Math.floor(n/86400),h=Math.floor(n%86400/3600),m=Math.floor(n%3600/60);return d?tr(`${d} д ${h} ч`,`${d}d ${h}h`):h?tr(`${h} ч ${m} мин`,`${h}h ${m}m`):tr(`${m} мин`,`${m}m`)}
async function load(){loading.value=true;error.value='';try{infrastructure.value=await api.infrastructure()}catch(e){error.value=e instanceof Error?e.message:tr('Не удалось загрузить обзор','Unable to load dashboard')}finally{loading.value=false}}
async function loadPresence(){if(!auth.can('users.read')||presenceLoading.value)return;presenceLoading.value=true;presenceError.value='';try{presence.value=await api.userPresence()}catch{presence.value=null;presenceError.value=tr('Не удалось загрузить пользователей онлайн. Повторите обновление.','Unable to load online users. Please refresh to retry.')}finally{presenceLoading.value=false}}
async function loadConnections(){if(auth.can('audit.read'))try{connections.value=await api.liveConnections()}catch{/* optional */}}
async function loadCluster(){if(auth.can('infrastructure.read'))try{cluster.value=await api.clusterState()}catch{/* optional */}}
async function loadOperations(){operationsError.value='';const [d,c]=await Promise.allSettled([api.diagnostics(),api.serviceCommands()]);if(d.status==='fulfilled')diagnostics.value=d.value;else operationsError.value=tr('Самодиагностика временно недоступна','Self-diagnostics are temporarily unavailable');if(c.status==='fulfilled')commands.value=Array.isArray(c.value)?c.value:[]}
async function loadLayout(){try{const v=await api.dashboardLayout();layout.value=clone(v);savedLayout.value=clone(v)}catch{/* use defaults */}}
async function reconcile(){commandBusy.value=true;try{await api.reconcileHBBS();await loadOperations()}catch(e){operationsError.value=e instanceof Error?e.message:tr('Команда не выполнена','Command failed')}finally{commandBusy.value=false}}
function beginCustomize(){savedLayout.value=clone(layout.value);layoutError.value='';customizing.value=true} function cancelCustomize(){layout.value=clone(savedLayout.value);customizing.value=false} function resetLayout(){layout.value={version:1,order:[...defaults],hidden:[]}}
function hideWidget(id:WidgetID){if(visible.value.length<=1){layoutError.value=tr('Нельзя скрыть последний виджет.','The last widget cannot be hidden.');return}layout.value.hidden.push(id)} function showWidget(id:WidgetID){layout.value.hidden=layout.value.hidden.filter(v=>v!==id)}
function moveWidget(id:WidgetID,delta:number){const order=[...layout.value.order],from=order.indexOf(id),to=Math.max(0,Math.min(order.length-1,from+delta));if(from!==to){order.splice(from,1);order.splice(to,0,id);layout.value.order=order}}
function dropWidget(target:WidgetID){const source=dragging.value;dragging.value=null;if(source&&source!==target){const order=[...layout.value.order],from=order.indexOf(source),to=order.indexOf(target);order.splice(from,1);order.splice(to,0,source);layout.value.order=order}}
async function saveLayout(){layoutBusy.value=true;layoutError.value='';try{const v=await api.saveDashboardLayout(layout.value);layout.value=clone(v);savedLayout.value=clone(v);customizing.value=false}catch(e){layoutError.value=e instanceof Error?e.message:tr('Не удалось сохранить раскладку','Unable to save layout')}finally{layoutBusy.value=false}}
let timer:number|undefined,clockTimer:number|undefined
onMounted(()=>{void load();void loadPresence();void loadConnections();void loadCluster();void loadOperations();void loadLayout();timer=window.setInterval(()=>{void load();void loadPresence();void loadConnections();void loadCluster();void loadOperations()},15000);clockTimer=window.setInterval(()=>now.value=new Date(),1000)})
onUnmounted(()=>{if(timer)clearInterval(timer);if(clockTimer)clearInterval(clockTimer)})
</script>
<template>
<section class="welcome-row"><div><p class="eyebrow">{{tr('Обзор удалённого управления','Remote control overview')}}</p><h2>{{t('welcome')}}, {{displayName}}.</h2><p>{{tr('Текущее состояние сервера, устройств и защищённых сессий.','Current state of the server, devices, and protected sessions.')}}</p></div><div class="dashboard-actions"><template v-if="customizing"><button class="secondary-button" @click="resetLayout"><RotateCcw :size="15"/>{{tr('По умолчанию','Reset')}}</button><button class="secondary-button" @click="cancelCustomize"><X :size="15"/>{{tr('Отмена','Cancel')}}</button><button class="primary-button compact" :disabled="layoutBusy" @click="saveLayout"><Check :size="15"/>{{tr('Сохранить','Save')}}</button></template><button v-else class="secondary-button" @click="beginCustomize"><Settings2 :size="15"/>{{tr('Настроить','Customize')}}</button><button v-if="!customizing" class="secondary-button" :disabled="loading" @click="load"><RefreshCw :size="15" :class="{spinning:loading}"/>{{t('refresh')}}</button><span v-if="!customizing" class="status-pill" :class="{degraded:!operational}"><span/>{{operational?t('operational'):tr('Сниженная доступность','Degraded')}}</span></div></section>
<p v-if="error" class="alert-error">{{error}}</p><p v-if="layoutError" class="alert-error">{{layoutError}}</p>
<section v-if="customizing&&hidden.length" class="dashboard-hidden"><span>{{tr('Скрытые виджеты','Hidden widgets')}}</span><button v-for="id in hidden" :key="id" @click="showWidget(id)">+ {{tr(...labels[id])}}</button></section>
<p v-if="operationsError" class="alert-error dashboard-operations-error">{{operationsError}}</p>
<section class="dashboard-widget-grid" :class="{customizing}">
<div v-for="id in visible" :key="id" class="dashboard-widget" :class="widgetClass(id)" :draggable="customizing" @dragstart="dragging=id" @dragend="dragging=null" @dragover.prevent @drop="dropWidget(id)">
<div v-if="customizing" class="widget-controls"><GripVertical :size="16"/><strong>{{tr(...labels[id])}}</strong><button @click="moveWidget(id,-1)"><MoveUp :size="14"/></button><button @click="moveWidget(id,1)"><MoveDown :size="14"/></button><button @click="hideWidget(id)"><EyeOff :size="14"/></button></div>
<MetricCard v-if="id==='online-devices'" :label="tr('Устройства в сети','Online devices')" :value="infrastructure?.online_devices??'—'" :detail="`${infrastructure?.managed_devices??0} ${tr('зарегистрировано','registered')}`" :icon="Boxes" tone="green"/>
<MetricCard v-else-if="id==='offline-devices'" :label="tr('Устройства офлайн','Offline devices')" :value="infrastructure?.offline_devices??'—'" :detail="tr('Нет heartbeat более 3 минут','No heartbeat for more than 3 minutes')" :icon="MonitorOff" tone="amber"/>
<MetricCard v-else-if="id==='users'" :label="t('users')" :value="infrastructure?.users??'—'" :detail="`${infrastructure?.active_sessions??0} ${tr('активных сессий','active sessions')}`" :icon="Users" tone="violet"/>
<MetricCard v-else-if="id==='users-online'" :label="tr('Пользователи онлайн','Users online')" :value="presence?.online??'—'" :detail="presenceError?tr('Данные недоступны','Data unavailable'):`${presence?.idle??0} ${tr('неактивны','idle')} · ${presence?.offline??0} ${tr('офлайн','offline')}`" :icon="Users" tone="green"><button v-if="!customizing" class="secondary-button presence-open" aria-haspopup="dialog" @click="openOnlineUsers">{{tr('Кто онлайн','Who is online')}}</button></MetricCard>
<MetricCard v-else-if="id==='active-connections'" :label="tr('Активные подключения','Active connections')" :value="connections?.active??'—'" :detail="`${connections?.stale??0} ${tr('без heartbeat','without heartbeat')} · ${connections?.closed??0} ${tr('завершено за 7 дней','closed in 7 days')}`" :icon="RadioTower" tone="cyan"/>
<MetricCard v-else-if="id==='cluster'" :label="tr('Узлы кластера','Cluster nodes')" :value="cluster?.nodes.length??'—'" :detail="`${cluster?.leases.length??0} ${tr('активных lease','active leases')}`" :icon="Network" tone="violet"/>
<MetricCard v-else-if="id==='rendezvous-peers'" label="Rendezvous peers" :value="infrastructure?.rendezvous_peers??'—'" :detail="`${infrastructure?.hbbs_instances??0} HBBS instance`" :icon="Server" tone="green"/>
<MetricCard v-else-if="id==='relay-load'" :label="tr('Relay-нагрузка','Relay load')" :value="infrastructure?.relay_connections??'—'" :detail="`${formatRate(infrastructure?.relay_bandwidth)} · ${infrastructure?.healthy_relays??0}/${infrastructure?.relay_servers??0} healthy`" :icon="Cable" tone="cyan"/>
<article v-else-if="id==='diagnostics'" class="panel diagnostics-panel"><div class="panel-heading"><div><p class="overline">Production diagnostics</p><h3>{{tr('Самодиагностика сервера','Server self-diagnostics')}}</h3></div><span class="badge" :class="diagnostics?.status==='ok'?'green':diagnostics?.status==='warning'?'amber':'danger'">{{diagnostics?.status||'—'}}</span></div><div class="diagnostic-compact"><div v-for="check in diagnostics?.checks||[]" :key="check.name" :class="check.status"><CheckCircle2 v-if="check.status==='ok'" :size="17"/><TriangleAlert v-else-if="check.status==='warning'" :size="17"/><CircleAlert v-else :size="17"/><div><strong>{{check.name}}</strong><small>{{check.message}}</small></div></div></div></article>
<article v-else-if="id==='hbbs-sync'" class="panel node-control-panel"><div class="panel-heading"><div><p class="overline">Server control</p><h3>{{tr('Синхронизация HBBS','HBBS synchronization')}}</h3></div><button class="secondary-button" :disabled="commandBusy" @click="reconcile"><RotateCw :size="15"/>{{tr('Синхронизировать','Reconcile')}}</button></div><p>{{tr('Принудительно обновляет users, sessions, ACL и Strategies в кеше HBBS.','Forces users, sessions, ACL, and Strategies to refresh in the HBBS cache.')}}</p><div class="command-compact"><div v-for="command in [...commands].reverse().slice(0,5)" :key="command.id"><span>{{command.type}}</span><small>{{command.target_instance||command.service}} · {{new Date(command.created_at).toLocaleString()}}</small><span class="badge" :class="command.acknowledged_at?'green':'neutral'">{{command.acknowledged_at?tr('выполнено','completed'):tr('ожидает','pending')}}</span></div><p v-if="!commands.length" class="muted-text">{{tr('Команд управления ещё не было.','No control commands yet.')}}</p></div></article>
<section v-else class="dashboard-status-strip"><div><Cpu :size="15"/><span>CPU</span><strong>{{(infrastructure?.cpu_percent??0).toFixed(1)}}%</strong><small>{{infrastructure?.cpu_count??0}} CPU</small></div><div><MemoryStick :size="15"/><span>RAM</span><strong>{{formatMemory(infrastructure?.memory_bytes)}}</strong></div><div><Timer :size="15"/><span>{{tr('Время работы','Uptime')}}</span><strong>{{formatUptime(infrastructure?.uptime_seconds)}}</strong></div><div><Clock3 :size="15"/><span>{{tr('Дата и время','Date and time')}}</span><strong>{{now.toLocaleString()}}</strong></div></section>
</div></section>
<dialog v-if="auth.can('users.read')" ref="presenceDialog" class="presence-dialog" aria-labelledby="presence-title">
<div class="presence-heading"><h3 id="presence-title">{{tr('Пользователи онлайн','Users online')}} <span v-if="presence">({{presence.online}})</span></h3><button class="secondary-button" :aria-label="tr('Закрыть','Close')" @click="presenceDialog?.close()"><X :size="18"/></button></div>
<p class="muted-text">{{tr('Активность действующей сессии за последние 3 минуты. Список обновляется каждые 15 секунд.','Activity in a valid session within the last 3 minutes. Refreshes every 15 seconds.')}}</p>
<div class="presence-tools"><label>{{tr('Поиск по имени, логину или устройству','Search name, username or device')}}<input v-model="presenceSearch" type="search" autocomplete="off" /></label><button class="secondary-button" :disabled="presenceLoading" @click="loadPresence"><RefreshCw :size="15" :class="{spinning:presenceLoading}"/>{{t('refresh')}}</button></div>
<p v-if="presenceError" class="alert-error" role="alert">{{presenceError}}</p>
<p v-else-if="presenceLoading&&!presence" role="status">{{tr('Загрузка пользователей…','Loading users…')}}</p>
<template v-else-if="presence">
<p v-if="!onlineUsers.length" role="status">{{tr('Сейчас нет пользователей онлайн.','No users are online right now.')}}</p>
<p v-else-if="!filteredOnlineUsers.length" role="status">{{tr('По вашему запросу никто не найден.','No users match your search.')}}</p>
<div v-else class="presence-table" :aria-busy="presenceLoading"><table><thead><tr><th>{{tr('Пользователь','User')}}</th><th>{{tr('Логин','Username')}}</th><th>{{tr('Последняя активность','Last activity')}}</th><th>{{tr('Последнее устройство','Last device')}}</th></tr></thead><tbody><tr v-for="user in filteredOnlineUsers" :key="user.user_id"><td>{{user.display_name||user.username}}</td><td>{{user.username}}</td><td>{{seenAt(user.last_seen_at)}}</td><td>{{user.client_device_id||'—'}}</td></tr></tbody></table></div>
</template>
</dialog>
</template>
<style scoped>
.presence-open{margin-top:12px}
.presence-dialog{width:min(900px,calc(100vw - 32px));max-height:85vh;overflow:auto;padding:24px;border:1px solid var(--border);border-radius:14px;background:var(--surface,#101e2d);color:var(--text,#dbe8f3)}
.presence-dialog::backdrop{background:rgb(0 0 0 / .55)}
.presence-heading,.presence-tools{display:flex;justify-content:space-between;gap:16px;align-items:center}
.presence-heading h3{margin:0}.presence-tools{margin:20px 0;align-items:end}.presence-tools label{display:grid;gap:8px;flex:1}.presence-tools input{width:100%;min-width:0;padding:10px;border:1px solid var(--border);border-radius:8px;background:transparent;color:inherit}
.presence-table{overflow:auto}.presence-table table{width:100%;text-align:left}.presence-table th,.presence-table td{padding:12px;overflow-wrap:anywhere}.presence-table th{white-space:nowrap}
.presence-open:focus-visible,.presence-dialog button:focus-visible,.presence-dialog input:focus-visible{outline:2px solid #31b9ad;outline-offset:3px}
@media(max-width:600px){.presence-dialog{padding:16px}.presence-tools{align-items:stretch;flex-direction:column}}
</style>
